import { test } from 'node:test';
import assert from 'node:assert/strict';
import { sanitizarEntrada, temSegredoVazado } from './solution.mjs';

test('sanitizarEntrada remove aspas e ponto e vírgula', () => {
  assert.equal(sanitizarEntrada("ana'; DROP"), 'ana DROP');
});

test('sanitizarEntrada mantém texto limpo e rejeita não-string', () => {
  assert.equal(sanitizarEntrada('João da Silva'), 'João da Silva');
  assert.equal(sanitizarEntrada(123), '');
});

test('temSegredoVazado encontra o segredo no código', () => {
  assert.equal(temSegredoVazado('const chave = "sk-abc";', ['sk-abc']), true);
});

test('temSegredoVazado devolve false com código limpo', () => {
  assert.equal(temSegredoVazado('const chave = "sk-abc";', ['sk-xyz']), false);
  assert.equal(temSegredoVazado('sem nada aqui', []), false);
});

solutionCode:
export function sanitizarEntrada(texto) {
  if (typeof texto !== 'string') return '';
  return texto
    .replace(/--/g, '')
    .replace(/['";]/g, '')
    .trim();
}

export function temSegredoVazado(codigo, segredos) {
  if (typeof codigo !== 'string' || !Array.isArray(segredos)) return false;
  return segredos.some(
    (segredo) => typeof segredo === 'string' && segredo !== '' && codigo.includes(segredo)
  );
}
